/**
 * Unit tests for CategoryPlot.removeDomainMarker.
 */
public class CategoryPlot_removeDomainMarker_TriageGen2Test {

    private CategoryPlot plot;
    private Marker mockMarker;
    private Marker anotherMarker;

    @Before
    public void setUp() throws Exception {
        plot = new CategoryPlot();
        mockMarker = mock(Marker.class);
        anotherMarker = mock(Marker.class);
    }

    /**
     * Helper method to inject markers into the private maps of CategoryPlot via reflection.
     */
    @SuppressWarnings("unchecked")
    private void injectMarkers(Layer layer, int index, ArrayList<Marker> markers) throws Exception {
        String fieldName = (layer == Layer.FOREGROUND) ? "foregroundDomainMarkers" : "backgroundDomainMarkers";
        Field field = CategoryPlot.class.getDeclaredField(fieldName);
        field.setAccessible(true);
        Map<Integer, ArrayList<Marker>> map = (Map<Integer, ArrayList<Marker>>) field.get(plot);
        map.put(index, markers);
    }

    @Test
    public void testRemoveDomainMarker_Foreground_Success_Notify() throws Exception {
        int index = 0;
        ArrayList<Marker> markers = new ArrayList<>();
        markers.add(mockMarker);
        injectMarkers(Layer.FOREGROUND, index, markers);

        // We can't easily verify fireChangeEvent() without a spy or subclass, 
        // but we can verify the return value and state change.
        boolean result = plot.removeDomainMarker(index, mockMarker, Layer.FOREGROUND, true);

        assertTrue("Marker should be removed", result);
        assertTrue("Marker list should be empty", markers.isEmpty());
    }

    @Test
    public void testRemoveDomainMarker_Foreground_Fail() throws Exception {
        int index = 0;
        ArrayList<Marker> markers = new ArrayList<>();
        markers.add(anotherMarker);
        injectMarkers(Layer.FOREGROUND, index, markers);

        boolean result = plot.removeDomainMarker(index, mockMarker, Layer.FOREGROUND, true);

        assertFalse("Should return false when marker not found", result);
        assertEquals("List size should remain 1", 1, markers.size());
    }

    @Test
    public void testRemoveDomainMarker_Background_Success_NoNotify() throws Exception {
        int index = 1;
        ArrayList<Marker> markers = new ArrayList<>();
        markers.add(mockMarker);
        injectMarkers(Layer.BACKGROUND, index, markers);

        boolean result = plot.removeDomainMarker(index, mockMarker, Layer.BACKGROUND, false);

        assertTrue("Marker should be removed", result);
        assertTrue("Marker list should be empty", markers.isEmpty());
    }

    @Test
    public void testRemoveDomainMarker_Background_Fail_NoNotify() throws Exception {
        int index = 1;
        ArrayList<Marker> markers = new ArrayList<>();
        markers.add(anotherMarker);
        injectMarkers(Layer.BACKGROUND, index, markers);

        boolean result = plot.removeDomainMarker(index, mockMarker, Layer.BACKGROUND, false);

        assertFalse("Should return false when marker not found", result);
        assertEquals("List size should remain 1", 1, markers.size());
    }

    @Test(expected = NullPointerException.class)
    public void testRemoveDomainMarker_NullLayer_ThrowsException() {
        // This tests the branch where layer is not FOREGROUND (it will go to else)
        // but the map access might fail if the map itself isn't initialized or index is missing.
        plot.removeDomainMarker(0, mockMarker, null, true);
    }

    @Test(expected = NullPointerException.class)
    public void testRemoveDomainMarker_IndexNotFound_ThrowsException() throws Exception {
        // Testing the behavior when the index does not exist in the map
        plot.removeDomainMarker(99, mockMarker, Layer.FOREGROUND, true);
    }
}
